class LRU:
    def __init__(self, cap):
        self.cap = cap
        self.d = {}
    def get(self, k):
        return self.d.get(k, -1)
    def put(self, k, v):
        if len(self.d) >= self.cap:
            self.d.pop(next(iter(self.d)))
        self.d[k] = v

def match(pat, s):
    import re
    return re.fullmatch(pat.replace('*', '.*'), s) is not None
